using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=key",
            "ShopDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change: The default discriminator property name
            // changed from "Discriminator" to "$type". For existing documents that
            // already store "Discriminator", explicitly configure the old name.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

// EF Core 9 breaking change: Synchronous I/O on Cosmos DB provider now throws
// InvalidOperationException. All queries/saves must use async methods.
class ProductService
{
    private readonly CosmosDbContext _db;

    public ProductService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 - no longer works):
    // public List<Product> GetAll() => _db.Products.ToList();
    // public void Save() => _db.SaveChanges();

    // AFTER (EF Core 9 - use async):
    public async Task<List<Product>> GetAllAsync()
        => await _db.Products.ToListAsync();

    public async Task SaveAsync()
        => await _db.SaveChangesAsync();
}

